1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Keepmark prototype</title>
7	  <style>
8	    :root { color-scheme: light; --ink:#14251d; --muted:#68756e; --line:#dce4df; --paper:#fbfcfa; --green:#176b47; --soft:#eef5f0; }
9	    * { box-sizing:border-box; }
10	    body { margin:0; background:#f2f4f0; color:var(--ink); font:15px/1.5 Inter, ui-sans-serif, system-ui, sans-serif; }
11	    button,input { font:inherit; }
12	    .shell { min-height:100vh; display:grid; grid-template-columns:220px 1fr; }
13	    aside { padding:30px 24px; border-right:1px solid var(--line); background:#f8faf7; }
14	    .brand { display:flex; gap:10px; align-items:center; font-size:19px; font-weight:750; letter-spacing:-.4px; margin-bottom:38px; }
15	    .brand-mark { width:29px; height:29px; border-radius:9px; display:grid; place-items:center; color:white; background:var(--green); font-size:16px; }
16	    nav a { display:flex; align-items:center; gap:10px; padding:10px 12px; margin:3px 0; border-radius:9px; color:#4d5b54; text-decoration:none; }
17	    nav a.active { color:var(--ink); background:#e9efe9; font-weight:650; }
18	    nav span { width:19px; text-align:center; }
19	    main { width:min(930px, calc(100vw - 270px)); margin:0 auto; padding:54px 28px; }
20	    .eyebrow { color:var(--green); font-size:13px; font-weight:750; letter-spacing:.08em; text-transform:uppercase; }
21	    h1 { font:700 36px/1.15 Georgia, serif; letter-spacing:-1px; margin:7px 0 8px; }
22	    .sub { color:var(--muted); margin:0 0 27px; }
23	    form { display:flex; gap:10px; padding:9px; border:1px solid #cbd6cf; background:white; border-radius:14px; box-shadow:0 9px 28px rgba(30,55,42,.07); }
24	    input { flex:1; min-width:0; border:0; outline:0; padding:9px 11px; color:var(--ink); }
25	    input::placeholder { color:#95a19a; }
26	    button { border:0; border-radius:9px; padding:10px 18px; font-weight:700; cursor:pointer; background:var(--green); color:white; }
27	    button:disabled { opacity:.7; cursor:wait; }
28	    .section-head { display:flex; justify-content:space-between; align-items:center; margin:44px 0 14px; }
29	    h2 { font-size:17px; margin:0; }
30	    .count { color:var(--muted); font-size:13px; }
31	    .empty { padding:56px 24px; border:1px dashed #cbd5cf; border-radius:14px; text-align:center; color:var(--muted); background:rgba(255,255,255,.45); }
32	    .empty strong { display:block; color:#425048; margin-bottom:4px; }
33	    .card { display:none; grid-template-columns:150px 1fr; overflow:hidden; background:white; border:1px solid var(--line); border-radius:14px; box-shadow:0 5px 18px rgba(30,55,42,.05); }
34	    .card.visible { display:grid; animation:up .25s ease-out; }
35	    .preview { min-height:145px; display:grid; place-items:center; color:#fff; background:linear-gradient(145deg,#314f88,#6b8ed5); font:700 42px Georgia, serif; }
36	    .content { padding:19px 21px 17px; }
37	    .site { display:flex; align-items:center; gap:7px; color:#617068; font-size:12px; }
38	    .favicon { display:grid; place-items:center; width:19px; height:19px; border-radius:5px; background:#111f3e; color:#fff; font-size:11px; font-weight:800; }
39	    h3 { margin:9px 0 5px; font:700 21px/1.25 Georgia, serif; }
40	    .description { color:#5d6b64; margin:0; max-width:590px; }
41	    .meta { display:flex; gap:8px; align-items:center; margin-top:14px; color:#879189; font-size:12px; }
42	    .pill { background:var(--soft); color:#42604e; padding:3px 8px; border-radius:20px; }
43	    .toast { position:fixed; right:24px; bottom:24px; padding:11px 15px; border-radius:10px; background:#173e2c; color:white; opacity:0; transform:translateY(8px); transition:.2s; }
44	    .toast.show { opacity:1; transform:none; }
45	    @keyframes up { from { opacity:0; transform:translateY(8px); } }
46	    @media (max-width:700px) { .shell{grid-template-columns:1fr} aside{display:none} main{width:100%;padding:32px 20px}.card{grid-template-columns:1fr}.preview{min-height:105px} }
47	  </style>
48	</head>
49	<body>
50	  <div class="shell" data-harness-ready="true">
51	    <aside>
52	      <div class="brand"><span class="brand-mark">K</span> Keepmark</div>
53	      <nav>
54	        <a class="active" href="#"><span>⌂</span> All bookmarks</a>
55	        <a href="#"><span>◷</span> Read later</a>
56	        <a href="#"><span>◇</span> Labels</a>
57	      </nav>
58	    </aside>
59	    <main>
60	      <div class="eyebrow">Your library</div>
61	      <h1>Save something worth returning to.</h1>
62	      <p class="sub">Paste a web address. The page details will be gathered for you.</p>
63	      <form id="saveForm">
64	        <input id="url" type="url" required aria-label="Web address" placeholder="Paste a web address…" autocomplete="off">
65	        <button id="saveButton" type="submit">Save bookmark</button>
66	      </form>
67	
68	      <div class="section-head">
69	        <h2>Recently saved</h2>
70	        <span class="count" id="count">0 bookmarks</span>
71	      </div>
72	      <div class="empty" id="empty"><strong>Your collection is empty</strong>Your first saved page will appear here.</div>
73	      <article class="card" id="card">
74	        <div class="preview">CSS</div>
75	        <div class="content">
76	          <div class="site"><span class="favicon">M</span><span id="host">developer.mozilla.org</span></div>
77	          <h3 id="title">CSS grid layout</h3>
78	          <p class="description" id="description">CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.</p>
79	          <div class="meta"><span class="pill">Saved just now</span><span id="displayUrl">developer.mozilla.org/en-US/docs/Web/CSS/grid</span></div>
80	        </div>
81	      </article>
82	    </main>
83	  </div>
84	  <div class="toast" id="toast" role="status">Bookmark saved</div>
85	  <script>
86	    const form = document.querySelector('#saveForm');
87	    const input = document.querySelector('#url');
88	    const button = document.querySelector('#saveButton');
89	    form.addEventListener('submit', (event) => {
90	      event.preventDefault();
91	      const parsed = new URL(input.value);
92	      button.disabled = true;
93	      button.textContent = 'Getting page details…';
94	      setTimeout(() => {
95	        const isMdn = parsed.hostname.includes('mozilla.org');
96	        document.querySelector('#host').textContent = parsed.hostname.replace(/^www\./, '');
97	        document.querySelector('#displayUrl').textContent = (parsed.hostname + parsed.pathname).replace(/^www\./, '');
98	        if (!isMdn) {
99	          document.querySelector('#title').textContent = 'A saved page from ' + parsed.hostname.replace(/^www\./, '');
100	          document.querySelector('#description').textContent = 'A short description gathered from the page will appear here.';
101	          document.querySelector('.preview').textContent = parsed.hostname.slice(0, 2).toUpperCase();
102	        }
103	        document.querySelector('#empty').style.display = 'none';
104	        document.querySelector('#card').classList.add('visible');
105	        document.querySelector('#count').textContent = '1 bookmark';
106	        input.value = '';
107	        button.disabled = false;
108	        button.textContent = 'Save bookmark';
109	        const toast = document.querySelector('#toast');
110	        toast.classList.add('show');
111	        setTimeout(() => toast.classList.remove('show'), 1800);
112	      }, 700);
113	    });
114	  </script>
115	</body>
116	</html>
