63	<body>
64	  <div class="shell" data-harness-ready="true">
65	    <aside>
66	      <div class="brand"><span class="brand-mark">K</span> Keepmark</div>
67	      <nav>
68	        <a class="active" href="#"><span>⌂</span> All bookmarks</a>
69	        <a href="#"><span>◷</span> Read later</a>
70	        <a href="#"><span>◇</span> Labels</a>
71	      </nav>
72	    </aside>
73	    <main>
74	      <div class="eyebrow">Your library</div>
75	      <h1>Save something worth returning to.</h1>
76	      <p class="sub">Paste a web address. The page details will be gathered for you.</p>
77	      <form id="saveForm">
78	        <input id="url" type="url" required aria-label="Web address" placeholder="Paste a web address…" autocomplete="off">
79	        <button id="saveButton" type="submit">Save bookmark</button>
80	      </form>
81	
82	      <div class="section-head">
83	        <h2>Recently saved</h2>
84	        <span class="count" id="count">0 bookmarks</span>
85	      </div>
86	      <div class="empty" id="empty"><strong>Your collection is empty</strong>Your first saved page will appear here.</div>
87	      <article class="card" id="card">
88	        <div class="preview">CSS</div>
89	        <div class="content">
90	          <div class="site"><span class="favicon">M</span><span id="host">developer.mozilla.org</span></div>
91	          <div id="displayDetails">
92	            <div class="card-top"><h3 id="title">CSS grid layout</h3><button class="edit-button" id="editButton" type="button">Edit details</button></div>
93	            <p class="description" id="description">CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.</p>
94	          </div>
95	          <form class="edit-form" id="inlineEdit">
96	            <label for="inlineTitle">Title</label><input id="inlineTitle" value="CSS grid layout">
97	            <label for="inlineDescription">Description</label><textarea id="inlineDescription" rows="3">CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.</textarea>
98	            <div class="edit-actions"><button class="cancel" type="button">Cancel</button><button type="submit">Save changes</button></div>
99	          </form>
100	          <div class="meta"><span class="pill">Saved just now</span><span id="displayUrl">developer.mozilla.org/en-US/docs/Web/CSS/grid</span></div>
101	        </div>
102	      </article>
103	    </main>
104	  </div>
105	  <div class="toast" id="toast" role="status">Bookmark saved</div>
106	  <div class="overlay" id="overlay">
107	    <form class="dialog" id="dialogEdit">
108	      <h2>Edit bookmark details</h2><p>The address and page image stay unchanged.</p>
109	      <label for="dialogTitle">Title</label><input id="dialogTitle" value="CSS grid layout">
110	      <label for="dialogDescription">Description</label><textarea id="dialogDescription" rows="4">CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.</textarea>
111	      <div class="edit-actions"><button class="cancel" type="button">Cancel</button><button type="submit">Save changes</button></div>
112	    </form>
113	  </div>
114	  <script>
115	    const form = document.querySelector('#saveForm');
116	    const input = document.querySelector('#url');
117	    const button = document.querySelector('#saveButton');
118	    const params = new URLSearchParams(location.search);
119	    const editMode = params.get('edit') || 'inline';
120	    if (params.get('state') === 'saved') {
121	      document.querySelector('#empty').style.display = 'none';
122	      document.querySelector('#card').classList.add('visible');
123	      document.querySelector('#count').textContent = '1 bookmark';
124	    }
125	    const showToast = (message) => {
126	      const toast = document.querySelector('#toast');
127	      toast.textContent = message;
128	      toast.classList.add('show');
129	      setTimeout(() => toast.classList.remove('show'), 1800);
130	    };
131	    document.querySelector('#editButton').addEventListener('click', () => {
132	      if (editMode === 'dialog') document.querySelector('#overlay').classList.add('visible');
133	      else {
134	        document.querySelector('#displayDetails').style.display = 'none';
135	        document.querySelector('#inlineEdit').classList.add('visible');
136	      }
137	    });
138	    const applyEdit = (title, description) => {
139	      document.querySelector('#title').textContent = title;
140	      document.querySelector('#description').textContent = description;
141	      document.querySelector('#displayDetails').style.display = '';
142	      document.querySelector('#inlineEdit').classList.remove('visible');
143	      document.querySelector('#overlay').classList.remove('visible');
144	      showToast('Changes saved');
145	    };
146	    document.querySelector('#inlineEdit').addEventListener('submit', e => { e.preventDefault(); applyEdit(document.querySelector('#inlineTitle').value, document.querySelector('#inlineDescription').value); });
147	    document.querySelector('#dialogEdit').addEventListener('submit', e => { e.preventDefault(); applyEdit(document.querySelector('#dialogTitle').value, document.querySelector('#dialogDescription').value); });
148	    document.querySelectorAll('.cancel').forEach(el => el.addEventListener('click', () => {
149	      document.querySelector('#displayDetails').style.display = '';
150	      document.querySelector('#inlineEdit').classList.remove('visible');
151	      document.querySelector('#overlay').classList.remove('visible');
152	    }));
153	    form.addEventListener('submit', (event) => {
154	      event.preventDefault();
155	      const parsed = new URL(input.value);
156	      button.disabled = true;
157	      button.textContent = 'Getting page details…';
158	      setTimeout(() => {
159	        const isMdn = parsed.hostname.includes('mozilla.org');
160	        document.querySelector('#host').textContent = parsed.hostname.replace(/^www\./, '');
161	        document.querySelector('#displayUrl').textContent = (parsed.hostname + parsed.pathname).replace(/^www\./, '');
162	        if (!isMdn) {
163	          document.querySelector('#title').textContent = 'A saved page from ' + parsed.hostname.replace(/^www\./, '');
164	          document.querySelector('#description').textContent = 'A short description gathered from the page will appear here.';
165	          document.querySelector('.preview').textContent = parsed.hostname.slice(0, 2).toUpperCase();
166	        }
167	        document.querySelector('#empty').style.display = 'none';
168	        document.querySelector('#card').classList.add('visible');
169	        document.querySelector('#count').textContent = '1 bookmark';
170	        input.value = '';
171	        button.disabled = false;
172	        button.textContent = 'Save bookmark';
173	        showToast('Bookmark saved');
174	      }, 700);
175	    });
176	  </script>
177	</body>
178	</html>
