98	            <label for="inlineAddress">Web address</label><input id="inlineAddress" type="url" value="https://developer.mozilla.org/en-US/docs/Web/CSS/grid">
99	            <label for="inlineTitle">Title</label><input id="inlineTitle" value="CSS grid layout">
100	            <label for="inlineDescription">Description</label><textarea id="inlineDescription" rows="3">CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.</textarea>
101	            <label for="inlineNote">Personal note</label><textarea id="inlineNote" rows="3" placeholder="Why are you saving this?"></textarea>
102	            <div class="edit-actions"><button class="cancel" type="button">Cancel</button><button type="submit">Save changes</button></div>
103	          </form>
104	          <p class="note" id="noteDisplay"></p>
105	          <div class="meta"><span class="pill">Saved just now</span><span id="displayUrl">developer.mozilla.org/en-US/docs/Web/CSS/grid</span></div>
106	        </div>
107	      </article>
108	    </main>
109	  </div>
110	  <div class="toast" id="toast" role="status">Bookmark saved</div>
111	  <div class="overlay" id="overlay">
112	    <form class="dialog" id="dialogEdit">
113	      <h2>Edit bookmark details</h2><p>The address and page image stay unchanged.</p>
114	      <label for="dialogTitle">Title</label><input id="dialogTitle" value="CSS grid layout">
115	      <label for="dialogDescription">Description</label><textarea id="dialogDescription" rows="4">CSS grid layout is a two-dimensional layout system for the web. It lets you arrange content in rows and columns.</textarea>
