117	    </form>
118	  </div>
119	  <script>
120	    const form = document.querySelector('#saveForm');
121	    const input = document.querySelector('#url');
122	    const button = document.querySelector('#saveButton');
123	    const params = new URLSearchParams(location.search);
124	    const editMode = params.get('edit') || 'inline';
125	    if (params.get('state') === 'saved') {
126	      document.querySelector('#empty').style.display = 'none';
127	      document.querySelector('#card').classList.add('visible');
128	      document.querySelector('#count').textContent = '1 bookmark';
129	    }
130	    const showToast = (message) => {
131	      const toast = document.querySelector('#toast');
132	      toast.textContent = message;
133	      toast.classList.add('show');
134	      setTimeout(() => toast.classList.remove('show'), 1800);
135	    };
136	    document.querySelector('#editButton').addEventListener('click', () => {
137	      if (editMode === 'dialog') document.querySelector('#overlay').classList.add('visible');
138	      else {
139	        document.querySelector('#displayDetails').style.display = 'none';
140	        document.querySelector('#inlineEdit').classList.add('visible');
141	      }
142	    });
143	    const applyEdit = (title, description, address, note) => {
144	      if (address) {
145	        const parsed = new URL(address);
146	        const cleanHost = parsed.hostname.replace(/^www\./, '');
147	        document.querySelector('#host').textContent = cleanHost;
148	        document.querySelector('#displayUrl').textContent = (parsed.hostname + parsed.pathname + parsed.search).replace(/^www\./, '');
149	        document.querySelector('.favicon').textContent = cleanHost.slice(0, 1).toUpperCase();
150	        document.querySelector('.preview').textContent = cleanHost.slice(0, 2).toUpperCase();
151	        if (params.get('address') === 'refetch' && cleanHost === 'web.dev') {
152	          title = 'Learn CSS: Flexbox';
153	          description = 'Learn how to use flexbox to create flexible layouts that adapt to different screen sizes.';
154	          document.querySelector('#inlineTitle').value = title;
155	          document.querySelector('#inlineDescription').value = description;
156	        }
157	      }
158	      document.querySelector('#title').textContent = title;
159	      document.querySelector('#description').textContent = description;
160	      const noteDisplay = document.querySelector('#noteDisplay');
161	      if (note) { noteDisplay.textContent = note; noteDisplay.classList.add('visible'); }
162	      else noteDisplay.classList.remove('visible');
163	      document.querySelector('#displayDetails').style.display = '';
164	      document.querySelector('#inlineEdit').classList.remove('visible');
165	      document.querySelector('#overlay').classList.remove('visible');
166	      showToast('Changes saved');
167	    };
168	    document.querySelector('#inlineEdit').addEventListener('submit', e => { e.preventDefault(); applyEdit(document.querySelector('#inlineTitle').value, document.querySelector('#inlineDescription').value, document.querySelector('#inlineAddress').value, document.querySelector('#inlineNote').value); });
169	    document.querySelector('#dialogEdit').addEventListener('submit', e => { e.preventDefault(); applyEdit(document.querySelector('#dialogTitle').value, document.querySelector('#dialogDescription').value); });
170	    document.querySelectorAll('.cancel').forEach(el => el.addEventListener('click', () => {
171	      document.querySelector('#displayDetails').style.display = '';
172	      document.querySelector('#inlineEdit').classList.remove('visible');
173	      document.querySelector('#overlay').classList.remove('visible');
174	    }));
175	    form.addEventListener('submit', (event) => {
176	      event.preventDefault();
177	      const parsed = new URL(input.value);
178	      button.disabled = true;
179	      button.textContent = 'Getting page details…';
180	      setTimeout(() => {
181	        const isMdn = parsed.hostname.includes('mozilla.org');
182	        document.querySelector('#host').textContent = parsed.hostname.replace(/^www\./, '');
183	        document.querySelector('#displayUrl').textContent = (parsed.hostname + parsed.pathname).replace(/^www\./, '');
184	        if (!isMdn) {
185	          document.querySelector('#title').textContent = 'A saved page from ' + parsed.hostname.replace(/^www\./, '');
186	          document.querySelector('#description').textContent = 'A short description gathered from the page will appear here.';
187	          document.querySelector('.preview').textContent = parsed.hostname.slice(0, 2).toUpperCase();
188	        }
189	        document.querySelector('#empty').style.display = 'none';
190	        document.querySelector('#card').classList.add('visible');
191	        document.querySelector('#count').textContent = '1 bookmark';
192	        input.value = '';
193	        button.disabled = false;
194	        button.textContent = 'Save bookmark';
195	        showToast('Bookmark saved');
196	      }, 700);
197	    });
198	  </script>
199	</body>
